"""Read only text metadata from the public Allen glyph-map ZIP."""

from hashlib import sha256
from io import RawIOBase
from pathlib import Path
from urllib.request import Request, urlopen
from zipfile import ZipFile


ROOT = Path(__file__).resolve().parent
URL = "https://ryanallen.com/voynich/glyph-map/glyph-map.zip"
LENGTH = 87500918
TAIL = (ROOT / "zip-tail.bin").read_bytes()
TAIL_START = LENGTH - len(TAIL)


class RemoteZip(RawIOBase):
    def __init__(self):
        self.offset = 0

    def seekable(self):
        return True

    def readable(self):
        return True

    def tell(self):
        return self.offset

    def seek(self, offset, whence=0):
        self.offset = (0, self.offset, LENGTH)[whence] + offset
        return self.offset

    def read(self, count=-1):
        start = self.offset
        end = LENGTH if count < 0 else min(LENGTH, start + count)
        if end <= start:
            return b""
        if start >= TAIL_START:
            payload = TAIL[start - TAIL_START:end - TAIL_START]
        else:
            header = {"Range": f"bytes={start}-{end - 1}", "User-Agent": "Voynich Swarm index audit/1"}
            with urlopen(Request(f"{URL}?span={start}-{end-1}", headers=header), timeout=22) as stream:
                if stream.headers.get("Content-Range") != f"bytes {start}-{end - 1}/{LENGTH}":
                    raise OSError(f"Unexpected ZIP range {stream.headers.get('Content-Range')}")
                payload = stream.read()
        self.offset = end
        return payload


if __name__ == "__main__":
    with ZipFile(RemoteZip()) as archive:
        for name in ("words.tsv", "pages.tsv"):
            payload = archive.read(f"glyph-map/{name}")
            (ROOT / name).write_bytes(payload)
            print(name, len(payload), sha256(payload).hexdigest())

code.prepare_decks.py:
"""Join a frozen ZL roster and render native Yale image regions for blind readers."""

from collections import defaultdict
from concurrent.futures import ThreadPoolExecutor
import csv
from hashlib import sha256
from io import BytesIO
import json
from pathlib import Path
import random
from statistics import median
from urllib.request import Request, urlopen

from PIL import Image, ImageDraw
from vs import corpus


ROOT = Path(__file__).resolve().parent
DECK = ROOT.parent / "coded-plume-board-390141"
ROSTER = json.loads((ROOT / "frozen-roster.json").read_text())
BODY = (242, 239, 235)
INK = (26, 33, 42)
MARK = (29, 106, 155)


def table(name):
    with (ROOT / name).open() as stream:
        return list(csv.DictReader(stream, delimiter="\t"))


def center(rect):
    x0, y0, x1, y1 = rect
    return (x0 + x1) / 2, (y0 + y1) / 2


def box(row):
    return tuple(int(row[key]) for key in ("box_x0", "box_y0", "box_x1", "box_y1"))


def title_card(card, text, xy):
    ImageDraw.Draw(card).text(xy, text, fill=INK)


def fitting(crop, limit):
    factor = min(limit[0] / crop.width, limit[1] / crop.height)
    return crop.resize((max(1, round(crop.width * factor)), max(1, round(crop.height * factor))),
                       Image.Resampling.LANCZOS)


def matches(page, line, coordinate_rows):
    found = {}
    for word_index, word in enumerate(line.words, 1):
        same = [
            row for row in coordinate_rows[page.id, line.n, word_index]
            if "".join(row["reading"].split()) == word
        ]
        if len(same) == 1 and all(same[0].get(key) for key in ("box_x0", "box_y0", "box_x1", "box_y1")):
            found[word_index] = same[0]
    return found


def nearby_word_boxes(rows, image, x, omit=None):
    choices = [box(row) for rank, row in rows.items() if row["image"] == image and rank != omit]
    choices = sorted(choices, key=lambda rect: abs(center(rect)[0] - x))
    return [rect for rect in choices[:3] if abs(center(rect)[0] - x) <= 550]


def recover_target(item, current, coordinates):
    rank = item["word_index"]
    before = [index for index in current if index < rank]
    after = [index for index in current if index > rank]
    if not before or not after:
        return None
    left_index, right_index = max(before), min(after)
    left, right = current[left_index], current[right_index]
    if left["image"] != right["image"]:
        return None
    left_box, right_box = box(left), box(right)
    candidates = [
        row for (page, line, _), rows in coordinates.items()
        if page == item["page"] and line == item["line"]
        for row in rows if row["image"] == left["image"] and "".join(row["reading"].split()) == item["word"]
        and all(row.get(key) for key in ("box_x0", "box_y0", "box_x1", "box_y1"))
        and center(left_box)[0] < center(box(row))[0] < center(right_box)[0]
    ]
    if len(candidates) == 1:
        row = candidates[0]
        return row["image"], box(row), row["trust"], "unique reading between exact anchors"
    if (left_index, right_index) != (rank-1, rank+1) or candidates:
        return None
    heights = [rect[3] - rect[1] for rect in (left_box, right_box)]
    reference_height = median(heights)
    gap = right_box[0] - left_box[2]
    y_difference = abs(center(left_box)[1] - center(right_box)[1])
    if not 0.5 * reference_height <= gap <= 4 * reference_height or y_difference > 0.7 * reference_height:
        return None
    region = (left_box[2], min(left_box[1], right_box[1])-8, right_box[0],
              max(left_box[3], right_box[3])+8)
    return left["image"], region, "no word box", "between exact adjacent word boxes"


def geometry(item, page, coordinates):
    lines = {line.n: line for line in page.lines if line.unit == "P"}
    current = matches(page, lines[item["line"]], coordinates)
    row = current.get(item["word_index"])
    if row is None:
        recovered = recover_target(item, current, coordinates)
        if recovered is None:
            return None
        image, target, trust, join = recovered
    else:
        image, target, trust, join = row["image"], box(row), row["trust"], "exact index and reading"
    x, y = center(target)
    own = nearby_word_boxes(current, image, x, item["word_index"])
    other = {}
    for delta in (-1, 1):
        n = item["line"] + delta
        if n in lines:
            other[delta] = nearby_word_boxes(matches(page, lines[n], coordinates), image, x)
    baseline = median(center(rect)[1] for rect in own) if own else None
    height = median(rect[3] - rect[1] for rect in own) if own else None
    gaps = {}
    if baseline is not None and height:
        for delta, neighbors in other.items():
            if neighbors:
                gap = (median(center(rect)[1] for rect in neighbors) - baseline) * delta
                if 0 < gap <= 6 * height:
                    gaps[str(delta)] = round(gap / height, 6)
    return {"image": image, "target": target, "center_x": x, "center_y": y, "neighbor_body_px": height,
            "gaps_relative_to_other_words": gaps, "own_neighbor_count": len(own), "trust": trust,
            "join": join}


def read_crop(asset, bounds):
    x0, y0, x1, y1 = bounds
    region = f"{x0},{y0},{x1 - x0},{y1 - y0}"
    url = asset["iiif_image"].replace("/full/full/0/default.jpg", f"/{region}/full/0/default.jpg")
    if url == asset["iiif_image"]:
        raise ValueError("Unrecognized IIIF asset syntax")
    cache = ROOT / "native-crop-cache" / (sha256(url.encode()).hexdigest() + ".jpg")
    if not cache.exists():
        req = Request(url, headers={"User-Agent": "Voynich Swarm paleographic comparison/1"})
        with urlopen(req, timeout=24) as response:
            cache.write_bytes(response.read())
    payload = cache.read_bytes()
    out = Image.open(BytesIO(payload)).convert("RGB")
    if out.size != (x1 - x0, y1 - y0):
        raise ValueError(f"Unexpected crop size {out.size} in {url}")
    return out, url, sha256(payload).hexdigest()


def card_for(row, assets):
    info = row["geometry"]
    asset = assets[info["image"]]
    width, height = int(asset["width"]), int(asset["height"])
    x0, y0, x1, y1 = info["target"]
    word_height = y1 - y0
    # Request a single native rectangle containing both detail and context.
    x_pad = max(110, (x1 - x0) // 2)
    y_pad = max(120, round(2.1 * word_height))
    outer = (max(0, x0 - x_pad), max(0, y0 - y_pad),
             min(width, x1 + x_pad), min(height, y1 + y_pad))
    native, url, checksum = read_crop(asset, outer)
    local = (x0-outer[0], y0-outer[1], x1-outer[0], y1-outer[1])
    detail_pad = max(8, round(0.16 * word_height))
    detail_box = (max(0, local[0] - detail_pad), max(0, local[1] - detail_pad),
                  min(native.width, local[2] + detail_pad), min(native.height, local[3] + detail_pad))
    detail = fitting(native.crop(detail_box), (275, 152))
    context = native.copy()
    pen = ImageDraw.Draw(context)
    pen.line((local[0], local[3]+6, local[2], local[3]+6), fill=MARK, width=max(3, word_height//33))
    context = fitting(context, (258, 152))
    panel = Image.new("RGB", (558, 185), BODY)
    panel.paste(detail, (8 + (275 - detail.width)//2, 26 + (152 - detail.height)//2))
    panel.paste(context, (290 + (258 - context.width)//2, 26 + (152 - context.height)//2))
    row.update(native_region=outer, crop_url=url, crop_sha256=checksum,
               native_image_sha256=asset["sha256"], native_canvas=asset["iiif_canvas"])
    return panel


def main():
    (ROOT / "native-crop-cache").mkdir(exist_ok=True)
    pages, _ = corpus.split_pages("practice", "zl")
    manuscript = {page.id: page for page in pages}
    assets = {row["image"]: row for row in table("pages.tsv")}
    coordinates = defaultdict(list)
    for row in table("words.tsv"):
        if row["locus"] and row["word"].isdigit():
            try:
                page, n = row["locus"].rsplit(".", 1)
                coordinates[page, int(n), int(row["word"])].append(row)
            except ValueError:
                pass
    rows = ROSTER["entries"]
    for row in rows:
        row["geometry"] = geometry(row, manuscript[row["page"]], coordinates)
        if row["geometry"] is None:
            row["failure"] = "no exact join or adequately anchored alternate"
    cards = {}
    targets = [index for index, row in enumerate(rows) if row["geometry"]]
    with ThreadPoolExecutor(max_workers=5) as pool:
        futures = {index: pool.submit(card_for, rows[index], assets) for index in targets}
        for index, result in futures.items():
            try:
                cards[index] = result.result()
            except (OSError, ValueError, KeyError) as error:
                rows[index]["failure"] = str(error)
    mapping = {}
    for which, seed in (("a", 390142), ("b", 390143)):
        directory = DECK / which
        directory.mkdir(parents=True, exist_ok=True)
        for previous in directory.glob("board-*.png"):
            previous.unlink()
        order = list(cards)
        random.Random(seed).shuffle(order)
        mapping[which] = {}
        for start in range(0, len(order), 6):
            slots = order[start:start+6]
            board = Image.new("RGB", (1116, 555), BODY)
            for position, identity in enumerate(slots):
                panel = cards[identity].copy()
                code = f"{which.upper()}{start+position+1:02d}"
                title_card(panel, code, (12, 7))
                title_card(panel, "word", (138, 7))
                title_card(panel, "nearby lines", (387, 7))
                board.paste(panel, ((position % 2)*558, (position // 2)*185))
                mapping[which][code] = identity
            board.save(directory / f"board-{start//6+1:02d}.png")
    (ROOT / "private-map.json").write_text(json.dumps({"mapping": mapping, "rows": rows}, indent=2) + "\n")
    print(json.dumps({"roster": len(rows), "joined": len(targets), "rendered": len(cards),
                      "all_failures": [row["failure"] for row in rows if "failure" in row]}, ensure_ascii=False))


if __name__ == "__main__":
    main()

code.evaluate_ratings.py:
"""Unmask independent ordinal ratings and compare bifolio-held-out feature sets."""

from collections import Counter
from hashlib import sha256
import json
from pathlib import Path
import re
from statistics import median

import numpy as np
from vs import ivtff


ROOT = Path(__file__).resolve().parent
SCORES = re.compile(r"^([AB]\d\d)\s+([CD?])\s+([TO?])\s+([SV?])(?:\s+(.*))?$")


def reader(name, crosswalk):
    path = ROOT / f"ratings-{name}.txt"
    ratings = {}
    for line in path.read_text().splitlines():
        if not line.strip():
            continue
        matched = SCORES.fullmatch(line.strip())
        if matched is None:
            raise ValueError(f"Malformed rating for reader {name}: {line}")
        code, contact, spacing, height, note = matched.groups()
        if code in ratings:
            raise ValueError(f"Duplicate rating {code}")
        ratings[code] = {"contact": contact, "spacing": spacing, "height": height}
        if note:
            ratings[code]["comment"] = note
    if set(ratings) != set(crosswalk):
        raise ValueError(f"Incomplete or extra card IDs for {name}")
    return {crosswalk[code]: row for code, row in ratings.items()}, sha256(path.read_bytes()).hexdigest()


def agreement(peer, key):
    rows = [(item["reader_a"][key], item["reader_b"][key]) for item in peer]
    known = [(a, b) for a, b in rows if a != "?" and b != "?"]
    return {
        "all": len(rows),
        "exact": sum(a == b for a, b in rows),
        "jointly_known": len(known),
        "agree_jointly_known": sum(a == b for a, b in known),
        "both_unknown": sum(a == b == "?" for a, b in rows),
        "reader_a_counts": dict(Counter(a for a, _ in rows)),
        "reader_b_counts": dict(Counter(b for _, b in rows)),
    }


def estimate_space(item):
    gaps = item["geometry"]["gaps_relative_to_other_words"]
    return min(gaps.values(), default=None)


def features(items, indices):
    continuous = []
    factors = []
    for i in indices:
        item = items[i]
        units = ivtff.segment(item["word"], "eva-basic")
        continuous.append([
            np.log(estimate_space(item)), (item["word_index"] - 1)/(item["words_on_line"] - 1),
            units.index("sh")/max(1, len(units)-1),
        ])
        factors.append((item["currier"], item["section"], item["hand"]))
    return np.asarray(continuous), factors


def matrix(items, train, test, with_hand):
    numeric_train, factor_train = features(items, train)
    numeric_test, factor_test = features(items, test)
    shift = numeric_train.mean(axis=0)
    scale = numeric_train.std(axis=0)
    scale[scale == 0] = 1
    total_factors = 3 if with_hand else 2
    levels = [sorted({row[i] for row in factor_train})[1:] for i in range(total_factors)]
    def combine(numeric, factors):
        indicators = np.array([
            [entry[i] == level for i, accepted in enumerate(levels) for level in accepted]
            for entry in factors
        ], dtype=float)
        return np.column_stack((np.ones(len(numeric)), (numeric-shift)/scale, indicators))
    return combine(numeric_train, factor_train), combine(numeric_test, factor_test)


def logit_loss(train, y, test, actual):
    penalty = np.eye(train.shape[1])
    penalty[0, 0] = 0
    coefficient = np.zeros(train.shape[1])
    for _ in range(80):
        linear = np.clip(train @ coefficient, -35, 35)
        prob = 1/(1+np.exp(-linear))
        gradient = train.T @ (prob-y) + penalty @ coefficient
        hessian = (train.T * (prob*(1-prob))) @ train + penalty
        change = np.linalg.solve(hessian, gradient)
        coefficient -= change
        if np.max(np.abs(change)) < 1e-8:
            break
    prediction = test @ coefficient
    return (np.logaddexp(0, prediction) - actual*prediction).tolist()


def leave_bifolio_out(items):
    # Compare both models on the same held-out words with training support for the observed labels.
    y = np.asarray([item["consensus"] == "C" for item in items], dtype=float)
    by_bifolio = {}
    excluded = []
    for group in sorted({item["bifolio"] for item in items}):
        train = [i for i, item in enumerate(items) if item["bifolio"] != group]
        test = [i for i, item in enumerate(items) if item["bifolio"] == group]
        held_supported = []
        for i in test:
            absent = [
                key for key in ("section", "currier", "hand")
                if not any(items[t][key] == items[i][key] for t in train)
            ]
            if not absent and len(set(y[train])) == 2:
                held_supported.append(i)
            else:
                excluded.append({"page": items[i]["page"], "line": items[i]["line"], "bifolio": group,
                                 "missing_training_factors": absent, "training_contact_classes": len(set(y[train]))})
        if held_supported:
            arms = []
            for with_hand in (False, True):
                x_train, x_test = matrix(items, train, held_supported, with_hand)
                arms.append(logit_loss(x_train, y[train], x_test, y[held_supported]))
            by_bifolio[group] = {"test_words": len(held_supported), "base_losses": arms[0], "plus_hand_losses": arms[1]}
    loss = lambda key: [value for fold in by_bifolio.values() for value in fold[key]]
    n = len(loss("base_losses"))
    return {
        "scored_words": n, "scored_bifolios": len(by_bifolio), "folds": by_bifolio,
        "comparison_excluded_words": len(excluded),
        "comparison_exclusions": excluded,
        "base_mean_log_loss": sum(loss("base_losses"))/n if n else None,
        "plus_hand_mean_log_loss": sum(loss("plus_hand_losses"))/n if n else None,
        "base_equal_bifolio_mean_log_loss": (
            sum(sum(fold["base_losses"])/fold["test_words"] for fold in by_bifolio.values())/len(by_bifolio)
            if by_bifolio else None
        ),
        "plus_hand_equal_bifolio_mean_log_loss": (
            sum(sum(fold["plus_hand_losses"])/fold["test_words"] for fold in by_bifolio.values())/len(by_bifolio)
            if by_bifolio else None
        ),
    }


def main():
    data = json.loads((ROOT / "private-map.json").read_text())
    a, a_hash = reader("a", data["mapping"]["a"])
    b, b_hash = reader("b", data["mapping"]["b"])
    assert set(a) == set(b)
    rows = data["rows"]
    for i in sorted(a):
        item = rows[i]
        item.update(reader_a=a[i], reader_b=b[i])
        item["consensus"] = a[i]["contact"] if a[i]["contact"] == b[i]["contact"] else "?"
    peer = [rows[i] for i in sorted(a)]
    exact = [row for row in peer if row["geometry"]["join"] == "exact index and reading"]
    primary = [row for row in exact if row["consensus"] in ("C", "D") and estimate_space(row) is not None]
    result = {
        "frozen_rating_hashes": {"reader_a": a_hash, "reader_b": b_hash},
        "contact_agreement": agreement(peer, "contact"),
        "spacing_agreement": agreement(peer, "spacing"),
        "height_agreement": agreement(peer, "height"),
        "exact_join_contact_agreement": agreement(exact, "contact"),
        "primary": {
            "words": len(primary), "bifolios": len({row["bifolio"] for row in primary}),
            "class_counts": dict(Counter(row["consensus"] for row in primary)),
            "median_spacing_by_contact": {
                label: median(values) for label in ("C", "D")
                if (values := [estimate_space(item) for item in primary if item["consensus"] == label])
            },
            "held_out_by_bifolio": leave_bifolio_out(primary),
        },
        "rows": rows,
    }
    print(json.dumps(result, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
